tasks.command:
& {
$captured = @(& node .local/blueprint-audit-run.mjs --snapshot-only)
if ($LASTEXITCODE -ne 0) { throw 'Source snapshot failed' }
$captured | Write-Output
$source = @($captured | Where-Object { $_ -match '^Snapshot: ' } | ForEach-Object { $_.Substring(10) })
if ($source.Count -ne 1) { throw 'Expected one source snapshot' }
& (Join-Path $env:JAVA_HOME 'bin/java.exe') -classpath (Join-Path $source[0] 'android/gradle/wrapper/gradle-wrapper.jar') org.gradle.wrapper.GradleWrapperMain -p (Join-Path $source[0] 'android') :app:testDebugUnitTest --tests com.community.platform.feature.community.CommunityClassificationTest --tests com.community.platform.feature.community.ModerationTest --tests com.community.platform.feature.messaging.MessagingTest --tests com.community.platform.feature.messaging.MessagingLiveTest --tests com.community.platform.feature.messaging.OutboxTest --tests com.community.platform.feature.realtime.LiveUpdatesTest --offline --console=plain --no-daemon --max-workers=2
if ($LASTEXITCODE -ne 0) { throw 'Native qualification regressions failed' }
}

& {
$busy = @(Get-CimInstance Win32_Process | Where-Object { ($_.Name -eq 'java.exe' -and $_.CommandLine -match 'GradleWrapperMain|Gradle Test Executor') -or $_.Name -match '^(qemu-system-x86_64(-headless)?|emulator)\.exe$' })
if ($busy.Count -gt 0) {
$busy | Select-Object ProcessId,ParentProcessId,Name,CommandLine | Format-List
throw 'Native resources are in use; no focused build was started.'
}
& node .local/blueprint-audit-run.mjs --android-focused .local/blueprint-audit-2026-10-03T10-49-07-626Z-4c7ae56f com.community.platform.feature.planning.TaskViewModelTest com.community.platform.feature.realtime.LiveUpdatesTest
if ($LASTEXITCODE -ne 0) { throw 'Focused planning and realtime verification failed; preserve the reports.' }
}

& {
& docker compose -f infra/compose.yaml up -d --no-build --pull never --no-recreate --wait db mail
if ($LASTEXITCODE -ne 0) { throw 'Database and mail startup failed' }
$head = @(& docker compose -f infra/compose.yaml exec -T db psql -U community -d community -At -c 'SELECT version_num FROM alembic_version')
if ($LASTEXITCODE -ne 0 -or ($head -join '').Trim() -ne '0040') { throw 'Database does not match qualification source migration 0040; no migration was attempted' }
& docker compose -f infra/compose.yaml start api identity-mail-worker reminder-worker export-worker account-deletion-worker
if ($LASTEXITCODE -ne 0) { throw 'Local API or worker startup failed' }
Write-Output 'Existing local services resumed against migration 0040; no rebuild, migration or reset.'
}
